import logging
from taf.internal.aashell.factory import AaShellFactory
from taf.collectors.core import Factory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AaShellCliFactory(Factory):
    """
    factory to create AaShell cli
    """

    def create(self, configuration, existing_arguments):
        """
        Create a AaShell collector

        :param dict configuration:
                collection of configuration parameters for the object to be created and other
                objects, that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: AaShell
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return AaShellFactory().create_aashell(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(AaShellCliFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        for parameter_name in ["host", "port", "hops", "forwarding_port"]:
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]

    @staticmethod
    def get_executor_of_aashell_cli(aashell):
        executor = None
        for hop in aashell.telnet_connection.prerequisites[0].prerequisites[:-1]:
            ssh_connection_property = AaShellCliFactory._extract_ssh_connection_property(hop)
            if executor:
                ssh_connection_property['proxy'] = executor
            executor = ssh_connection_property
        return executor

    @staticmethod
    def _extract_ssh_connection_property(hop):
        ssh_connection_property = {}
        for parameter in ['_host', '_port', '_user', '_password', '_pkey', '_key_filename']:
            if getattr(hop.ssh_connections[0], parameter):
                ssh_connection_property[parameter[1:]] = getattr(hop.ssh_connections[0], parameter)
        return ssh_connection_property
